"""Input discovery helpers for local zizmor inputs."""
from dataclasses import dataclass
from pathlib import Path
import fnmatch
import os
import re


@dataclass
class Input:
    path: str
    kind: str
    text: str


def classify(path: str, text: str) -> str | None:
    name = Path(path).name.lower()
    if name in ('dependabot.yml', 'dependabot.yaml') or '.github/dependabot.' in path.replace('\\', '/'):
        return 'dependabot'
    if name in ('action.yml', 'action.yaml'):
        return 'actions'
    if '/.github/workflows/' in ('/' + path.replace('\\', '/')):
        return 'workflows'
    if re.search(r'(?m)^\s*(?:on|jobs)\s*:', text):
        return 'workflows'
    if re.search(r'(?m)^\s*(?:runs|inputs|outputs)\s*:', text):
        return 'actions'
    if re.search(r'(?m)^\s*updates\s*:', text):
        return 'dependabot'
    return None


def _ignored(rel: str, rules: list[str]) -> bool:
    ignored = False
    for line in rules:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        negate = line.startswith('!')
        pat = line[1:] if negate else line
        pat = pat.rstrip('/')
        matched = fnmatch.fnmatch(rel, pat) or fnmatch.fnmatch('/' + rel, pat)
        if matched:
            ignored = negate
    return ignored


def _read(path: Path, given: str, explicit: bool = False):
    try:
        data = path.read_text(encoding='utf-8')
    except (OSError, UnicodeError):
        return None
    kind = classify(given, data)
    if explicit and kind is None:
        # Explicit YAML files are passed to the validator as candidate inputs.
        if path.suffix.lower() in ('.yml', '.yaml'):
            kind = 'workflows'
    return Input(given, kind, data) if kind else None


def collect(paths, kinds=None, stdin_text=None, respect_gitignore=True):
    """Return (inputs, invalid_paths); kinds uses workflows/actions/dependabot/all."""
    kinds = set(kinds or ('workflows', 'actions', 'dependabot'))
    if 'all' in kinds or 'default' in kinds:
        kinds = {'workflows', 'actions', 'dependabot'}
    records, invalid = [], []
    if '-' in paths:
        if len(paths) != 1:
            return [], list(paths)
        content = stdin_text if stdin_text is not None else ''
        kind = classify('stdin.yml', content)
        if kind in kinds:
            records.append(Input('<stdin>', kind, content))
        return records, invalid
    for value in paths:
        p = Path(value)
        if not p.exists():
            invalid.append(value)
            continue
        if p.is_file():
            rec = _read(p, value, True)
            if rec and rec.kind in kinds:
                records.append(rec)
            else:
                invalid.append(value)
            continue
        if not p.is_dir():
            invalid.append(value)
            continue
        root = p.resolve()
        ignore_rules = []
        if respect_gitignore:
            for ig in root.rglob('.gitignore'):
                try:
                    ignore_rules += ig.read_text(errors='replace').splitlines()
                except OSError:
                    pass
        for child in sorted(root.rglob('*')):
            if not child.is_file():
                continue
            rel = child.relative_to(root).as_posix()
            if respect_gitignore and _ignored(rel, ignore_rules):
                continue
            rec = _read(child, str(child))
            if rec and rec.kind in kinds:
                records.append(rec)
    return records, invalid
"""Small handlers for zizmor's informational command-line modes."""
from pathlib import Path
import sys

VERSION = "zizmor 1.25.2\n"
SHELLS = {"bash", "elvish", "fish", "nushell", "powershell", "zsh"}
BASE = Path(__file__).with_name("cli_completions")


def handle(argv):
    """Return (handled, stdout, stderr, status), or handled=False.

    Call before the main argument parser. It handles only modes that exit
    before auditing; ordinary arguments are left to the caller.
    """
    args = list(argv)
    if "--version" in args or "-V" in args:
        return True, VERSION, "", 0
    if "--help" in args or "-h" in args:
        return False, "", "", 0
    if "--completions" in args:
        try:
            i = args.index("--completions")
            shell = args[i + 1]
        except (ValueError, IndexError):
            return False, "", "", 0
        if shell not in SHELLS:
            return False, "", "", 0
        return True, (BASE / (shell + ".completion")).read_text(), "", 0
    if "--thanks" in args:
        if len(args) != 1:
            return False, "", "", 0
        return True, (BASE / "thanks.txt").read_text(), "", 0
    if "--lsp" in args and len(args) == 1:
        return True, "", "", 0
    return False, "", "", 0


def emit_if_handled(argv):
    handled, out, err, status = handle(argv)
    if handled:
        sys.stdout.write(out)
        sys.stderr.write(err)
        return status
    return None
"""Lightweight source scanner for unpinned GitHub Actions ``uses`` values."""
import re


_SHA = re.compile(r"^[0-9a-fA-F]{40}$")


def detect_unpinned_uses(text):
    """Return ``(line_number, value)`` pairs for remotely referenced unpinned uses.

    Line numbers are 1-based. Local actions and Docker images are excluded.
    """
    found = []
    for number, line in enumerate(text.splitlines(), 1):
        m = re.match(r"^\s*uses\s*:\s*(.*?)\s*(?:#.*)?$", line)
        if not m:
            continue
        value = m.group(1).strip().strip("\"'")
        if not value or value.startswith("./") or value.startswith("docker://"):
            continue
        if "@" not in value:
            # Remote actions without a ref are invalid/implicitly unpinned too.
            found.append((number, value))
            continue
        ref = value.rsplit("@", 1)[1]
        if not _SHA.fullmatch(ref):
            found.append((number, value))
    return found
"""Small offline detector for zizmor's self-hosted-runner audit."""
import re


def detect_self_hosted(text):
    """Return (line_number, source_line) for runs-on values containing self-hosted.

    The caller owns YAML parsing and finding serialization; line numbers are 1-based.
    This accepts scalar and flow-sequence runner declarations, including quoted values.
    """
    results = []
    lines = text.splitlines()
    in_runs_on = False
    runs_indent = -1
    seq_indent = -1
    for number, line in enumerate(lines, 1):
        stripped = line.strip()
        indent = len(line) - len(line.lstrip())
        if not stripped or stripped.startswith('#'):
            continue
        key = re.match(r'^\s*runs-on\s*:\s*(.*)$', line)
        if key:
            value = key.group(1).split('#', 1)[0].strip()
            if re.search(r'(?<![\w-])self-hosted(?![\w-])', value.strip('"\'')):
                results.append((number, line))
            in_runs_on = value in ('', '|', '>')
            runs_indent = indent
            seq_indent = -1
            continue
        if in_runs_on:
            if indent <= runs_indent:
                in_runs_on = False
            elif re.match(r'^\s*-\s*', line):
                if seq_indent < 0:
                    seq_indent = indent
                item = re.sub(r'^\s*-\s*', '', line).split('#', 1)[0].strip().strip('"\'')
                if item == 'self-hosted':
                    results.append((number, line))
                continue
            else:
                in_runs_on = False
    return results

