"""Source scanner for the dangerous-triggers workflow audit."""
import re


def detect_dangerous_triggers(text):
    """Return ``(1-based line, trigger)`` pairs for dangerous workflow events."""
    lines = text.splitlines()
    hits = []
    in_on = False
    on_indent = -1
    for i, line in enumerate(lines):
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        indent = len(line) - len(line.lstrip())
        m = re.match(r'^\s*on\s*:\s*(.*)$', line)
        if m:
            in_on = True
            on_indent = indent
            value = m.group(1).split('#', 1)[0]
            trigger = next((t for t in ('pull_request_target', 'workflow_run')
                            if re.search(r'(?<![\w-])' + t + r'(?![\w-])', value)), None)
            if trigger:
                hits.append((i + 1, trigger))
            continue
        if in_on:
            if indent <= on_indent:
                in_on = False
            else:
                value = line.split('#', 1)[0]
                trigger = next((t for t in ('pull_request_target', 'workflow_run')
                                if re.search(r'(?<![\w-])' + t + r'(?![\w-])', value)), None)
                if trigger:
                    hits.append((i + 1, trigger))
    return hits

